def generate_parentheses(n):
    cur = [""]
    for _ in range(2 * n):
        nxt = []
        for s in cur:
            opens = s.count("(")
            closes = s.count(")")
            if opens < n:
                nxt.append(s + "(")
            if closes < opens:
                nxt.append(s + ")")
        cur = nxt
    return sorted(cur)

